def island_perimeter(grid):
    land = 0
    shared = 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 1:
                land += 1
                if r + 1 < len(grid) and grid[r + 1][c] == 1:
                    shared += 1
                if c + 1 < len(grid[r]) and grid[r][c + 1] == 1:
                    shared += 1
    return land * 4 - 2 * shared

print(island_perimeter(grid))

